const d=(e,r)=>{if(e){const t=new RegExp(`(.{${r}}).*`);return e.replace(t,"$1...")}else return""},p=e=>{const r=parseFloat(String(e));return(r%1!==0?r.toFixed(2):String(r)).replace(/\B(?=(\d{3})+(?!\d))/g,",")},i=e=>parseFloat(String(e)).toFixed(2).replace(/\.00$/,"")+"%",m=(e,r="yyyy-MM-dd HH:ss:mm")=>{const t=new Date(e);if(isNaN(t.getTime()))return"";const n=t.getFullYear(),a=String(t.getMonth()+1).padStart(2,"0"),s=String(t.getDate()).padStart(2,"0"),o=String(t.getHours()).padStart(2,"0"),c=String(t.getMinutes()).padStart(2,"0"),g=String(t.getSeconds()).padStart(2,"0");return r.replace("yyyy",String(n)).replace("MM",a).replace("dd",s).replace("HH",o).replace("mm",c).replace("ss",g)};export{m as f,p as n,d as r,i as t};
